function artistPageBack(){
 if(artistBackPending)return;
 if(history.state?.echoArtist?.token===artistHistoryToken){artistBackPending=true;history.back()}
 else if(artistPanel?.type==='release')showSavedArtist();else restoreArtistOrigin();
}
window.addEventListener('popstate',event=>{
 artistBackPending=false;const route=event.state?.echoArtist;
 if(route?.token===artistHistoryToken&&getTrack(route.trackId)){
  if(!route.releaseId&&lastArtistView?.track.id===route.trackId){beginArtistRoute(route.trackId,null,false);++artistEpoch;artistController?.abort();const saved=lastArtistView;artistPanel={tab:saved.tab};renderArtistProfile(saved.profile,saved.track);window.scrollTo({top:saved.scrollTop||0,behavior:'instant'})}
  else if(route.releaseId&&lastArtistView?.track.id===route.trackId)openArtistRelease(route.releaseId,{push:false});
  else openArtist(route.trackId,{push:false}).then(()=>{if(route.releaseId&&view==='artist'&&lastArtistView?.track.id===route.trackId)openArtistRelease(route.releaseId,{push:false})});
 }else if(view==='artist')restoreArtistOrigin();
});
const artistService=new EchoArtistService(window.ECHO_CONFIG||{});
let artistEpoch=0,artistController=null,artistPanel=null,lastArtistView=null;
function profileSourceLink(id,type){return type==='artist'&&/^UC[A-Za-z0-9_-]{22}$/.test(id||'')?'https://music.youtube.com/channel/'+id:type==='release'&&/^MPRE[A-Za-z0-9_-]{8,180}$/.test(id||'')?'https://music.youtube.com/browse/'+id:null}
function releaseDateMarkup(record){const value=EchoReleaseDate(record.releaseDate,record.datePrecision);return value?`<time data-release-date="${esc(record.releaseDate)}" data-date-precision="${esc(record.datePrecision||'')}" translate="no">${esc(value)}</time>`:'<span>暂无发行日期</span>'}
function renderArtistProfile(profile,track){
 const albums=Array.isArray(profile.albums)?profile.albums:[],singles=Array.isArray(profile.singles)?profile.singles:[],tab=artistPanel?.tab||(albums.length?'albums':singles.length?'singles':'albums'),records=tab==='singles'?singles:albums;
 presentArtistPage('歌手',`<article class="artist-profile"><div class="artist-hero"><img class="artist-photo" src="${esc(safeArtwork(profile.cover||track.cover))}" alt=""><div><small>歌手</small><h2 class="artist-name" translate="no">${esc(profile.name||track.artist)}</h2></div></div>${profile.description?`<p class="artist-bio" translate="no" tabindex="0">${esc(profile.description)}</p>`:'<p class="artist-status">暂无歌手简介</p>'}<div class="artist-tabs" role="group" aria-label="发行作品"><button data-artist-tab="albums" class="${tab==='albums'?'active':''}" aria-pressed="${tab==='albums'}">专辑 <span>${albums.length}</span></button><button data-artist-tab="singles" class="${tab==='singles'?'active':''}" aria-pressed="${tab==='singles'}">单曲与 EP <span>${singles.length}</span></button></div>${records.length?`<div class="artist-releases">${records.map(record=>`<button class="artist-release" data-artist-release="${esc(record.id)}"><img src="${esc(safeArtwork(record.cover||profile.cover||track.cover))}" alt="" loading="lazy"><strong translate="no">${esc(record.title)}</strong><small>${releaseDateMarkup(record)}</small></button>`).join('')}</div>`:'<p class="artist-status">暂未查到此类发行作品。</p>'}<div class="section-heading"><h2>当前歌曲</h2></div>${sheetTrack(track)}${profile.unavailable?'<div class="artist-footer"><button class="text-button" id="artist-retry">重试</button></div>':''}</article>`);
 artistPanel={type:'artist',track,profile,tab};lastArtistView={profile,track,tab};
}
async function openArtist(id,{push=true}={}){
 const track=getTrack(id);if(!track)return;if(track.remote)rememberOnline();beginArtistRoute(id,null,push);const epoch=++artistEpoch;artistController?.abort();artistController=new AbortController();lastArtistView=null;
 presentArtistPage('歌手',`<div class="artist-hero"><img class="artist-photo" src="${esc(track.cover)}" alt=""><div><small>歌手</small><h2 class="artist-name" translate="no">${esc(track.artist)}</h2></div></div><p class="catalog-loading" role="status">正在加载歌手资料…</p>`);artistPanel={type:'artist',track};
 try{const profile=await artistService.artist(track,{signal:artistController.signal});if(epoch===artistEpoch&&view==='artist')renderArtistProfile(profile,track)}
 catch(error){if(epoch===artistEpoch&&view==='artist'&&error.name!=='AbortError')renderArtistProfile({name:track.artist,cover:track.cover,description:null,albums:[],singles:[],unavailable:true},track)}
}
function showSavedArtist(){if(!lastArtistView)return;if(history.state?.echoArtist?.token===artistHistoryToken&&history.state.echoArtist.releaseId){artistPageBack();return}const saved=lastArtistView;++artistEpoch;artistController?.abort();artistPanel={tab:saved.tab};renderArtistProfile(saved.profile,saved.track);window.scrollTo({top:saved.scrollTop||0,behavior:'instant'})}
async function openArtistRelease(id,{push=true}={}){
 if(lastArtistView)lastArtistView.scrollTop=window.scrollY||0;
 const epoch=++artistEpoch;artistController?.abort();artistController=new AbortController();const known=[...(lastArtistView?.profile?.albums||[]),...(lastArtistView?.profile?.singles||[])].find(item=>item.id===id);
 beginArtistRoute(lastArtistView?.track.id||activeTrack().id,id,push);
 presentArtistPage('发行作品',`<button class="artist-return" id="artist-return">返回歌手</button><h2 translate="no">${esc(known?.title||'')}</h2><p class="catalog-loading" role="status">正在加载发行作品…</p>`);artistPanel={type:'release',releaseId:id};
 try{
  const release=await artistService.release(id,{signal:artistController.signal});if(epoch!==artistEpoch||view!=='artist')return;
  const songs=(release.tracks||[]).filter(song=>/^[A-Za-z0-9_-]{11}$/.test(song.videoId||'')).map(song=>{const item=youtubeTrack({...song,album:release.title,cover:song.cover||release.cover,artist:song.artist||release.artist||lastArtistView?.profile.name});const existing=getTrack(item.id);if(existing){Object.assign(existing,item);return existing}tracks.push(item);return item});
  const rank={year:1,month:2,day:3},record=known&&EchoReleaseDate(known.releaseDate,known.datePrecision)&&(!EchoReleaseDate(release.releaseDate,release.datePrecision)||String(known.releaseDate).slice(0,4)===String(release.releaseDate).slice(0,4)&&(rank[known.datePrecision]||0)>(rank[release.datePrecision]||0))?known:release;
  presentArtistPage('发行作品',`<article class="artist-profile"><button class="artist-return" id="artist-return">返回歌手</button><div class="artist-hero"><img class="profile-release-cover" src="${esc(safeArtwork(release.cover||known?.cover||'assets/disc-cover.svg'))}" alt=""><div><h2 class="release-title" translate="no">${esc(release.title)}</h2><p translate="no">${esc(release.artist||lastArtistView?.profile.name||'')}</p><p class="release-date"><span>${record.datePrecision==='year'?'发行年份':'发行日期'}</span> ${releaseDateMarkup(record)}</p></div></div>${songs.length?`<div class="artist-sheet-actions"><button class="primary-btn" id="play-release-all">${icon('play')} 播放全部</button></div><div class="sheet-song-list">${songs.map(song=>sheetTrack(song)).join('')}</div>`:'<p class="artist-status">该发行作品暂无可播放曲目。</p>'}</article>`);artistPanel={type:'release',releaseId:id,release,songs};
 }catch(error){if(epoch!==artistEpoch||view!=='artist'||error.name==='AbortError')return;presentArtistPage('发行作品','<button class="artist-return" id="artist-return">返回歌手</button><h2>发行作品暂时不可用</h2><p>请稍后重试。</p><button class="primary-btn" id="release-retry">重试</button>');artistPanel={type:'release',releaseId:id}}
}
document.addEventListener('echo:languagechange',()=>{for(const node of document.querySelectorAll('[data-release-date]'))node.textContent=EchoReleaseDate(node.dataset.releaseDate,node.dataset.datePrecision)||node.dataset.releaseDate});

function adHelperHelp(){openSheet('Safari 广告跳过',`<h2>Safari 广告跳过</h2><p>请在 Userscripts 中更新已安装脚本至 0.2.0；只刷新网页不会更新旧脚本。</p><p>需要免费的 Userscripts Safari 扩展，普通网页无法自行取得这项权限。</p><p class="helper-status" data-ad-helper-status role="status"></p><label class="setting-row" for="ad-helper-enabled"><span>允许广告跳过脚本</span><input id="ad-helper-enabled" type="checkbox" ${EchoAdHelper.enabled?'checked':''}></label><ol class="setup-steps"><li><a class="sheet-link" href="https://apps.apple.com/app/userscripts/id1463298887" target="_blank" rel="noopener">安装 Userscripts</a></li><li>在 iPhone 设置中启用 Safari 的 Userscripts 扩展，并允许它访问 Echo、youtube.com 和 youtube-nocookie.com。</li><li><a class="sheet-link" href="echo-ad-skip.user.js" target="_blank" rel="noopener">用 Safari 打开跳广告脚本</a><p>打开 Safari 的扩展菜单，选择 Userscripts 并安装脚本。也可以将下载的文件保存到 Userscripts 指定的文件夹。</p></li><li>回到 Echo 刷新页面，再播放音乐；上方会显示脚本是否已连接。</li></ol><p>脚本尝试点击跳过按钮，并对明确标记的广告静音和加速。新版增加多视频检测与播放前静音保护；连接状态不代表广告已跳过，部分广告仍需要等待。</p><p>此方案用于 Safari；iPhone Chrome 无法加载 Safari 扩展。</p><a class="secondary-btn" href="echo-ad-skip.user.js" download>下载脚本文件</a>`);EchoAdHelper.update()}
function setVolume(value){player.setVolume(value)}
function updateVolumeControls(value){const npVolume=$('#np-volume');npVolume.value=value;npVolume.style.setProperty('--value',`${value*100}%`);npVolume.setAttribute('aria-valuetext',Math.round(value*100)+'%');$('#np-volume-value').textContent=Math.round(value*100)+'%';$('#np-volume-toggle').style.opacity=Number(value)===0?'.4':'1';$('#np-volume-toggle').setAttribute('aria-label',Number(value)===0?'Unmute':'Mute');$('#volume').value=value;$('#volume').style.setProperty('--value',`${value*100}%`);$('#volume-toggle').style.opacity=Number(value)===0?'.4':'1';const setting=$('#settings-volume');if(setting){setting.value=value;setting.style.setProperty('--value',`${value*100}%`)}}
function openDatabase(){return new Promise((resolve,reject)=>{const request=indexedDB.open('echo-library',1);request.onupgradeneeded=()=>request.result.createObjectStore('songs',{keyPath:'id'});request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)})}
function dbRequest(mode,operation){return new Promise((resolve,reject)=>{if(!db)return reject(new Error('Storage unavailable'));const transaction=db.transaction('songs',mode),store=transaction.objectStore('songs');const request=operation(store);transaction.oncomplete=()=>resolve(request?.result);transaction.onerror=()=>reject(transaction.error);transaction.onabort=()=>reject(transaction.error)})}
function fileDuration(src){return new Promise(resolve=>{const a=new Audio();const timer=setTimeout(()=>{a.removeAttribute('src');resolve(0)},5000);a.preload='metadata';a.onloadedmetadata=()=>{clearTimeout(timer);resolve(Number.isFinite(a.duration)?a.duration:0);a.removeAttribute('src')};a.onerror=()=>{clearTimeout(timer);resolve(0)};a.src=src})}
async function importFiles(files,release=null){let count=0,failed=0;const importedIds=[];toast('Adding your music…');for(const file of files){if(!file.type.startsWith('audio/')&&!/\.(mp3|m4a|wav|ogg|flac|aac)$/i.test(file.name)){failed++;continue}if(tracks.some(t=>t.fingerprint===`${file.name}-${file.size}-${file.lastModified}`))continue;const src=URL.createObjectURL(file),duration=await fileDuration(src);if(!duration){URL.revokeObjectURL(src);failed++;continue}const name=file.name.replace(/\.[^.]+$/,'');const parts=name.split(' - '),artist=parts.length>1?parts.shift():'Your music',title=parts.join(' - ');const t={id:'local-'+crypto.randomUUID(),title:release?.title||title,artist:release?.artist||artist,album:release?.album||'On your device',mood:release?.mood||'Imported',duration,cover:release?.cover||'assets/city.jpg',local:true,fingerprint:`${file.name}-${file.size}-${file.lastModified}`,file,src};try{await dbRequest('readwrite',store=>store.put({...t,src:undefined}));tracks.push(t);importedIds.push(t.id);count++}catch{URL.revokeObjectURL(src);failed++}}$('#file-input').value='';if(view==='artist')dismissArtistRoute();if(view!=='library')view='library';render();toast(`${count} ${count===1?'song':'songs'} added${failed?`. ${failed} could not be saved or played.`:'. Your music, right here.'}`);return importedIds}
async function deleteTrack(id){const t=getTrack(id);try{await dbRequest('readwrite',s=>s.delete(id))}catch{toast('This file could not be removed.');return}if(current===id){player.select('sanctuary',{autoplay:false})}player.forget(id);URL.revokeObjectURL(t.src);tracks=tracks.filter(t=>t.id!==id);liked.delete(id);playlists.forEach(p=>p.ids=p.ids.filter(i=>i!==id));save('likes',[...liked]);save('queue',queue);save('current',current);save('playlists',playlists);sheet.close();render();updatePlayer();toast('Song removed from this browser.')}
