 if(data.share){const url=new URL(location.href);url.hash='track='+encodeURIComponent(data.share);try{await navigator.clipboard.writeText(url.href);toast('Song link copied')}catch{openSheet('SHARE THIS SONG',`<h2>A good song to share.</h2><label class="form-field">Select and copy this link<input value="${esc(url.href)}" readonly id="share-link"></label>`);$('#share-link').select()}}
