document.addEventListener('pointerdown',e=>{if(['seek','np-seek'].includes(e.target.id))seekEditing.add(e.target.id)});
document.addEventListener('pointerup',()=>{const position=[...seekDrafts.values()].at(-1);seekDrafts.clear();seekEditing.clear();if(Number.isFinite(position))player.seek(position);updateProgress()});
document.addEventListener('pointercancel',()=>{seekDrafts.clear();seekEditing.clear();updateProgress()});
document.addEventListener('input',e=>{const id=e.target.id;if(id==='music-search'){query=e.target.value;renderResults()}if(id==='volume'||id==='settings-volume'||id==='np-volume'){setVolume(e.target.value);e.target.style.setProperty('--value',`${e.target.value*100}%`);if(Number(e.target.value)>0)save('last-volume',Number(e.target.value))}if(id==='seek'||id==='np-seek'){const position=Number(e.target.value)/100*(player.getSnapshot().duration||activeTrack().duration);if(seekEditing.has(id))seekDrafts.set(id,position);else player.seek(position);updateProgress()}});
document.addEventListener('change',e=>{if(e.target.id==='theme-setting')EchoAppearance.setTheme(e.target.value);if(e.target.id==='ambient-setting')EchoAppearance.setAmbient(e.target.checked);if(e.target.id==='ad-helper-enabled')EchoAdHelper.setEnabled(e.target.checked);if(e.target.id==='language-setting')EchoI18n.setLanguage(e.target.value);if(e.target.id==='sleep-setting'){if(sleepTimer)clearTimeout(sleepTimer.id);const minutes=Number(e.target.value);sleepTimer=minutes?{minutes,id:setTimeout(()=>{player.pause();sleepTimer=null;toast('Sleep timer finished. Rest well.')},minutes*60000)}:null;toast(minutes?`Music will pause in ${minutes} minutes`:'Sleep timer off')}});
document.addEventListener('submit',e=>{if(e.target.id!=='playlist-form')return;e.preventDefault();const name=$('#playlist-name').value.trim();if(!name)return;const id='playlist-'+crypto.randomUUID(),track=e.target.dataset.track;playlists.push({id,title:name,ids:track?[track]:[],cover:track?getTrack(track).cover:'assets/sea.jpg'});save('playlists',playlists);cloudPlaylist(playlists[playlists.length-1]);sheet.close();render();toast('歌单已创建')});
$('#file-input').addEventListener('change',e=>importFiles([...e.target.files]));
$('#release-file-input').addEventListener('change',async e=>{const ids=await importFiles([...e.target.files],selectedRelease);e.target.value='';if(ids?.length){sheet.close();playTrack(ids[0],[ids[0]]);openNowPlaying()}});
$('#lyrics-file-input').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const target=current;if(file.size>250000){toast('Choose a lyrics file smaller than 250 KB.');e.target.value='';return}const text=await file.text(),parsed=parseLrc(text);if(!parsed.lines.length){toast('This file contains no lyric lines.');e.target.value='';return}save('lyrics-'+target,{text,name:file.name});if(target===current){sheet.close();loadLyrics(activeTrack(),true)}e.target.value='';toast('Lyrics saved for this song')});
document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault()});document.addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();importFiles([...e.dataTransfer.files])}});
[sheet,now].forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}}));
document.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select,button,a')||sheet.open)return;if(e.code==='Space'){e.preventDefault();togglePlay()}if(e.key==='ArrowRight'){e.preventDefault();player.seekBy(10)}if(e.key==='ArrowLeft'){e.preventDefault();player.seekBy(-10)}});
const CATALOG_API='https://api.audius.co/v1';
let searchSource='youtube',searchCategory='全部',catalogResults=[],catalogOffset=0,catalogHasMore=false,catalogLoading=false,catalogController=null,catalogTimer=null,catalogEpoch=0;
function cancelCatalog(){cancelYouTubeSearch();cancelReleaseSearch();clearTimeout(catalogTimer);catalogController?.abort();catalogEpoch++;catalogLoading=false}
function streamable(t){return t&&/^[a-zA-Z0-9]+$/.test(t.id)&&t.is_streamable===true&&!t.is_stream_gated&&t.is_available!==false&&t.access?.stream!==false&&!t.is_delete&&Number(t.duration)>0}
function safeArtwork(value){return EchoMusicLibrary.cover(value)}
function mapCatalogTrack(t){return {id:'audius-'+t.id,title:t.title||'Untitled',artist:t.user?.name||t.user?.handle||'Audius artist',album:t.genre||'Audius',mood:[t.mood,t.genre,t.tags].filter(Boolean).join(' · '),duration:Number(t.duration),cover:safeArtwork(t.artwork?.['1000x1000']||t.artwork?.['480x480']||t.artwork?.['150x150']),src:`${CATALOG_API}/tracks/${encodeURIComponent(t.id)}/stream?app_name=Echo`,remote:true,permalink:t.permalink?.startsWith('/')?'https://audius.co'+t.permalink:'https://audius.co',provider:'Audius'}}
function rememberOnline(){const keep=new Set([current,...liked,...queue,...playlists.flatMap(p=>p.ids)]);const remote=tracks.filter(t=>t.remote),saved=[...remote.filter(t=>keep.has(t.id)),...remote.filter(t=>!keep.has(t.id)).slice(-80)];save('online-tracks',saved)}
async function catalogRequest(path,params={},signal){const url=new URL(CATALOG_API+path);url.searchParams.set('app_name','Echo');for(const[k,v]of Object.entries(params))url.searchParams.set(k,String(v));const response=await fetch(url,{signal,credentials:'omit',headers:{Accept:'application/json'}});if(!response.ok)throw new Error(response.status===429?'Audius is receiving too many requests. Please try again shortly.':'The online catalog is temporarily unavailable.');const result=await response.json();if(!result.data)throw new Error('The catalog returned an unexpected response. Please try again.');return result}
function scheduleCatalog(wait=320){cancelCatalog();catalogResults=[];catalogOffset=0;catalogHasMore=false;const container=$('#search-results');if(!container)return;container.innerHTML='<div class="catalog-loading" role="status">正在搜索音乐库…</div>';catalogTimer=setTimeout(()=>fetchCatalog(false),wait)}
async function fetchCatalog(append=false){if(catalogLoading||view!=='search'||searchSource!=='online')return;catalogLoading=true;const epoch=catalogEpoch,term=[query.trim(),searchCategory!=='全部'?searchCategory:''].filter(Boolean).join(' '),offset=append?catalogOffset:0;catalogController=new AbortController();const controller=catalogController,timeout=setTimeout(()=>controller.abort(),14000);if(append){const b=$('#catalog-more');if(b){b.disabled=true;b.textContent='正在加载…'}}try{const result=await catalogRequest(term?'/tracks/search':'/tracks/trending',term?{query:term,limit:24,offset}:{time:'week',limit:24,offset},controller.signal);if(epoch!==catalogEpoch||view!=='search'||searchSource!=='online')return;if(!Array.isArray(result.data))throw new Error('The catalog returned an unexpected response.');const found=result.data.filter(streamable).map(mapCatalogTrack),merged=new Map(tracks.map(t=>[t.id,t]));for(const t of found)merged.set(t.id,t);tracks=[...merged.values()];catalogResults=append?[...new Map([...catalogResults,...found].map(t=>[t.id,t])).values()]:found;catalogOffset=offset+result.data.length;catalogHasMore=result.data.length===24;renderCatalogResults();}catch(error){if(epoch!==catalogEpoch||view!=='search'||searchSource!=='online')return;const message=error.name==='AbortError'?'The music catalog took too long to respond. Please try again.':error.message;if(append){toast(message);const b=$('#catalog-more');if(b){b.disabled=false;b.textContent='加载更多'}}else $('#search-results').innerHTML=empty('The music will be back.',message,`<button class="primary-btn" id="catalog-retry">Try again ${icon('arrow')}</button>`)}finally{clearTimeout(timeout);if(epoch===catalogEpoch)catalogLoading=false}}
function renderCatalogResults(){const container=$('#search-results');if(!container)return;container.innerHTML=`<div class="search-heading"><h2>${query.trim()?'搜索结果':'热门音乐'}</h2><span>${catalogResults.length} 首</span></div>${catalogResults.length?trackRows(catalogResults):empty('没有找到歌曲','请尝试其他歌曲或歌手。')}${catalogHasMore?'<div class="catalog-more"><button class="secondary-btn" id="catalog-more">加载更多</button></div>':''}`}
document.addEventListener('error',e=>{if(e.target.tagName==='IMG'&&!e.target.dataset.artworkEvents&&e.target.getAttribute('src')!=='assets/disc-cover.svg')e.target.src='assets/disc-cover.svg'},true);

let lyricTrackId=null,lyricLines=[],lyricSynced=false,lyricActive=-2,lyricFollow=true,lyricController=null,lyricEpoch=0,lyricsVisible=read('lyrics-visible',window.innerWidth>640);
const lyricCache=new Map(),lyricRetryAt=new Map();
function parseLrc(text){const timed=[],plain=[];let offset=0;for(const line of text.replace(/^\uFEFF/,'').split(/\r?\n/)){const off=line.match(/^\[offset:([+-]?\d+)\]/i);if(off){offset=Number(off[1])/1000;continue}const matches=[...line.matchAll(/\[(\d{1,3}):(\d{2})(?:[.:](\d{1,3}))?\]/g)],words=line.replace(/\[[^\]]*\]/g,'').trim();if(matches.length){for(const m of matches)if(words)timed.push({time:Number(m[1])*60+Number(m[2])+Number((m[3]||'0').padEnd(3,'0'))/1000,text:words})}else if(words&&!/^\[[a-z]+:/i.test(line))plain.push({time:null,text:words})}if(timed.length){const grouped=new Map();for(const line of timed.sort((a,b)=>a.time-b.time)){const time=Math.max(0,line.time-offset);grouped.set(time,grouped.has(time)?grouped.get(time)+'\n'+line.text:line.text)}return {synced:true,lines:[...grouped].map(([time,text])=>({time,text}))}}return {synced:false,lines:plain}}
function openNowPlaying(){EchoAppearance.setNowPlaying(true,activeTrack());if(!now.open)nowTrigger=document.activeElement;updatePlayer();if(!now.open){now.dataset.mode='audio';now.showModal()}document.body.classList.add('now-open');now.setAttribute('aria-modal','true');now.classList.toggle('lyrics-visible',lyricsVisible);$('#toggle-lyrics').classList.toggle('active-control',lyricsVisible);$('#toggle-lyrics').setAttribute('aria-pressed',lyricsVisible);loadLyrics(activeTrack());requestAnimationFrame(()=>{syncLyrics(player.getSnapshot().position,true);$('#close-now').focus({preventScroll:true})})}
function toggleLyrics(){lyricsVisible=!lyricsVisible;save('lyrics-visible',lyricsVisible);now.classList.toggle('lyrics-visible',lyricsVisible);$('#toggle-lyrics').classList.toggle('active-control',lyricsVisible);$('#toggle-lyrics').setAttribute('aria-pressed',lyricsVisible);requestAnimationFrame(()=>{if(lyricsVisible)syncLyrics(player.getSnapshot().position,true)})}
function lyricState(title,message,action=true){$('#lyrics-status').textContent='歌词';$('#lyrics-scroll').classList.remove('plain-lyrics');$('#lyrics-scroll').innerHTML=`<div class="lyrics-state"><h3>${esc(title)}</h3>${message?`<p>${esc(message)}</p>`:''}${action?'<div class="lyrics-state-actions"><button class="lyrics-text-button" id="retry-lyrics">重试</button><button class="lyrics-text-button" id="import-lyrics">导入歌词</button></div>':''}</div>`;$('#lyrics-follow').hidden=true}
async function loadLyrics(t,force=false){const key=JSON.stringify([t.id,t.title,t.artist,Math.round(t.duration||0)]);if(key===lyricTrackId&&!force&&(lyricLines.length||t.instrumental||!lyricRetryAt.has(key)))return;lyricTrackId=key;lyricLines=[];lyricSynced=false;lyricActive=-2;lyricFollow=true;lyricController?.abort();const epoch=++lyricEpoch;const imported=read('lyrics-'+t.id,null);if(imported?.text){showLyrics(parseLrc(imported.text),'已导入歌词',null);return}if(t.instrumental){lyricState('纯音乐','此曲目没有歌词。',false);return}if(lyricCache.has(key)&&!force){renderLyricRecord(lyricCache.get(key));return}if(!force&&(lyricRetryAt.get(key)||0)>Date.now()){lyricState('暂无匹配歌词','可以重试，或导入 LRC 歌词。');return}lyricState('加载歌词…','',false);const title=cleanLyricTitle(t.title),artist=t.artist.replace(/\s+-\s+Topic$/i,'').trim();lyricController=new AbortController();const controller=lyricController,timeout=setTimeout(()=>controller.abort(),14000);try{const url=new URL('https://lrclib.net/api/get');url.searchParams.set('track_name',title);url.searchParams.set('artist_name',artist);if(t.duration>0)url.searchParams.set('duration',String(Math.round(t.duration)));const response=await fetch(url,{signal:controller.signal,credentials:'omit',headers:{Accept:'application/json'}});if(epoch!==lyricEpoch)return;let record=null;if(response.ok)record=await response.json();else if(response.status!==404)throw new Error(response.status===429?'歌词服务繁忙，请稍后重试。':'暂时无法加载歌词。');if(!record||(!record.syncedLyrics&&!record.plainLyrics&&!record.instrumental)){const search=new URL('https://lrclib.net/api/search');search.searchParams.set('track_name',title);search.searchParams.set('artist_name',artist);const fallback=await fetch(search,{signal:controller.signal,credentials:'omit',headers:{Accept:'application/json'}});if(!fallback.ok)throw new Error('暂时无法加载歌词。');const records=await fallback.json();if(Array.isArray(records))record=bestLyricRecord(records,{...t,title,artist})}if(epoch!==lyricEpoch)return;if(!record){lyricRetryAt.set(key,Date.now()+30000);lyricTrackId=null;lyricState('暂无匹配歌词','试试导入 LRC 歌词。');return}lyricCache.set(key,record);lyricRetryAt.delete(key);renderLyricRecord(record)}catch(error){if(epoch!==lyricEpoch)return;lyricRetryAt.set(key,Date.now()+30000);lyricTrackId=null;lyricState('歌词暂不可用',error.name==='AbortError'?'加载超时，请重试。':error.message)}finally{clearTimeout(timeout)}}
function cleanLyricTitle(title){return title.replace(/\s*[\[(](?:official[^\])]*|music video|m\/?v|lyrics?[^\])]*|audio|visuali[sz]er)[\])]/gi,'').replace(/\s+/g,' ').trim()}
function lyricKey(value){return String(value||'').normalize('NFKC').toLowerCase().replace(/[^\p{L}\p{N}]/gu,'')}
function bestLyricRecord(records,track){const title=lyricKey(track.title),artist=lyricKey(track.artist);return records.filter(r=>r&&(r.syncedLyrics||r.plainLyrics||r.instrumental)).map(record=>{const recordTitle=lyricKey(record.trackName||record.name),recordArtist=lyricKey(record.artistName),difference=track.duration&&record.duration?Math.abs(track.duration-record.duration):0;const titleMatch=recordTitle===title,artistMatch=!!artist&&!!recordArtist&&(artist===recordArtist||artist.includes(recordArtist)||recordArtist.includes(artist));return {record,score:titleMatch&&artistMatch&&difference<=(track.provider==='youtube'?35:8)?10+(record.syncedLyrics?2:0)-difference/100:-1}}).filter(item=>item.score>=0).sort((a,b)=>b.score-a.score)[0]?.record||null}
function renderLyricRecord(record){if(record.instrumental){lyricState('纯音乐','此曲目没有歌词。',false);return}const text=record.syncedLyrics||record.plainLyrics;if(!text){lyricState('暂无匹配歌词','可以导入自己的歌词文件。');return}showLyrics(parseLrc(text))}
function showLyrics(parsed){if(!parsed.lines.length){lyricState('暂无歌词','可以导入 LRC 或文本歌词。');return}lyricLines=parsed.lines;lyricSynced=parsed.synced;lyricActive=-2;$('#lyrics-status').textContent=lyricSynced?'同步歌词':'歌词 · 未同步';$('#lyrics-follow').hidden=true;$('#lyrics-scroll').classList.toggle('plain-lyrics',!lyricSynced);$('#lyrics-scroll').innerHTML=`<div class="lyrics-lines">${lyricLines.map((line,i)=>lyricSynced?`<button class="lyric-line" data-lyric-index="${i}" data-time="${line.time}" aria-label="跳转到 ${format(line.time)}">${esc(line.text)}</button>`:`<p class="lyric-line">${esc(line.text)}</p>`).join('')}</div>`;requestAnimationFrame(()=>syncLyrics(player.getSnapshot().position,true))}
function syncLyrics(time,force=false){if(!now.open||!lyricsVisible||!lyricSynced||!lyricLines.length)return;const offset=Number(read('lyric-offset-'+current,0)),position=time-offset;let low=0,high=lyricLines.length-1,index=-1;while(low<=high){const middle=Math.floor((low+high)/2);if(lyricLines[middle].time<=position){index=middle;low=middle+1}else high=middle-1}if(index===lyricActive&&!force)return;lyricActive=index;const container=$('#lyrics-scroll'),elements=$$('.lyric-line',container);elements.forEach((line,i)=>{line.classList.toggle('is-current',i===index);line.classList.toggle('is-past',i<index);if(i===index)line.setAttribute('aria-current','true');else line.removeAttribute('aria-current')});$('#lyrics-follow').hidden=lyricFollow;if(lyricFollow){const target=elements[Math.max(0,index)];if(target){const top=container.scrollTop+target.getBoundingClientRect().top-container.getBoundingClientRect().top-container.clientHeight*.36+target.clientHeight*.5;container.scrollTo({top:Math.max(0,top),behavior:force||window.matchMedia?.('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'})}}}
function lyricsOptions(){const t=activeTrack();openSheet('歌词',`<h2>歌词设置</h2><div class="action-menu"><button id="import-lyrics">${icon('upload')} 导入歌词</button><button id="retry-lyrics">${icon('repeat')} 重新查询</button>${t.local?`<button id="edit-track-metadata">${icon('disc')} 编辑歌曲资料</button>`:''}${read('lyrics-'+current,null)?`<button id="clear-imported-lyrics">${icon('close')} 移除导入的歌词</button>`:''}</div><label class="form-field" for="lyric-offset">歌词偏移（秒）<input id="lyric-offset" type="number" min="-30" max="30" step="0.1" value="${Number(read('lyric-offset-'+current,0))}"></label><p>正值延后，负值提前。点击同步歌词可跳转播放进度。</p>`)}
function editTrackMetadata(id){const t=getTrack(id);if(!t?.local)return;openSheet('SONG DETAILS',`<h2>Find the right words.</h2><p>Accurate song titles and artist names help match lyrics.</p><form id="metadata-form" data-track="${esc(id)}"><label class="form-field">Song title<input name="title" value="${esc(t.title)}" required maxlength="180"></label><label class="form-field">Artist<input name="artist" value="${esc(t.artist)}" required maxlength="180"></label><label class="form-field">Album<input name="album" value="${esc(t.album)}" maxlength="180"></label><button class="primary-btn" type="submit">Save song details</button></form>`)}
document.addEventListener('click',e=>{const line=e.target.closest('[data-lyric-index]');if(!line)return;const duration=audio.duration;if(!Number.isFinite(duration))return;const offset=Number(read('lyric-offset-'+current,0));lyricFollow=true;player.seek(Number(line.dataset.time)+offset);updateProgress();syncLyrics(player.getSnapshot().position,true)});
for(const name of ['wheel','touchmove'])$('#lyrics-scroll').addEventListener(name,()=>{lyricFollow=false;if(lyricSynced)$('#lyrics-follow').hidden=false},{passive:true});
document.addEventListener('input',e=>{if(e.target.id==='lyric-offset'){const value=Math.max(-30,Math.min(30,Number(e.target.value)||0));save('lyric-offset-'+current,value);syncLyrics(player.getSnapshot().position,true)}});
document.addEventListener('submit',async e=>{if(e.target.id!=='metadata-form')return;e.preventDefault();const t=getTrack(e.target.dataset.track),data=new FormData(e.target);const title=String(data.get('title')).trim(),artist=String(data.get('artist')).trim();if(!title||!artist)return;const updated={...t,title,artist,album:String(data.get('album')).trim()||'On your device'};try{await dbRequest('readwrite',store=>store.put({...updated,src:undefined}));Object.assign(t,updated);lyricCache.delete(t.id);sheet.close();render();updatePlayer();if(now.open)loadLyrics(t,true);toast('Song details saved')}catch{toast('Song details could not be saved.')}});

const releases=new Map();
let releaseController=null,releaseTimer=null,releaseEpoch=0,selectedRelease=null,releaseRegion=read('release-region','us');
function cancelReleaseSearch(){clearTimeout(releaseTimer);releaseController?.abort();releaseEpoch++}
function scheduleReleaseSearch(wait=350){cancelReleaseSearch();const area=$('#search-results');if(!area)return;area.innerHTML=`<div class="release-region"><label for="release-region">Catalog region</label><select id="release-region"><option value="us">United States</option><option value="kr">South Korea</option><option value="jp">Japan</option><option value="gb">United Kingdom</option><option value="tw">Taiwan</option></select></div><div id="release-results"></div>`;$('#release-region').value=releaseRegion;if(!query.trim()){$('#release-results').innerHTML=empty('Find the music you love.','Search a K-pop artist, a song title, or an album. Release details come from Apple’s catalog. Use your own audio file for full playback here.');return}$('#release-results').innerHTML='<div class="catalog-loading" role="status">Searching official releases…</div>';releaseTimer=setTimeout(fetchReleases,wait)}
async function fetchReleases(){const epoch=releaseEpoch;releaseController=new AbortController();const controller=releaseController,timeout=setTimeout(()=>controller.abort(),12000);const url=new URL('https://itunes.apple.com/search');for(const[k,v]of Object.entries({term:query.trim(),entity:'song',media:'music',limit:50,country:releaseRegion}))url.searchParams.set(k,v);try{const response=await fetch(url,{signal:controller.signal,credentials:'omit'});if(!response.ok)throw new Error('The release catalog is temporarily unavailable. Please try again.');const data=await response.json();if(epoch!==releaseEpoch||view!=='search'||searchSource!=='catalog')return;const result=(data.results||[]).filter(t=>t.kind==='song'&&t.trackId).map(t=>({id:'apple-'+t.trackId,title:t.trackName,artist:t.artistName,album:t.collectionName||'',duration:t.trackTimeMillis/1000,cover:safeArtwork(t.artworkUrl100?.replace('100x100bb','600x600bb')),mood:t.primaryGenreName||'',url:t.trackViewUrl,region:releaseRegion}));result.forEach(t=>releases.set(t.id,t));$('#release-results').innerHTML=`<div class="section-heading"><div><h2>Official releases</h2><p>${result.length} results · Details and links from Apple</p></div></div>${result.length?`<div class="release-list">${result.map(t=>`<button class="release-row" data-release="${esc(t.id)}" aria-label="View ${esc(t.title)} by ${esc(t.artist)}"><img src="${esc(t.cover)}" alt=""><span><strong>${esc(t.title)}</strong><small>${esc(t.artist)} · ${esc(t.album)}</small></span><span class="release-time">${format(t.duration)}</span>${icon('arrow')}</button>`).join('')}</div>`:empty('Try another title or region.','No releases matched this search in the selected catalog.')}`}catch(error){if(epoch!==releaseEpoch)return;const area=$('#release-results');if(area)area.innerHTML=empty('The catalog will be back.',error.name==='AbortError'?'The search took too long. Try again.':error.message,'<button class="primary-btn" id="retry-releases">Try again</button>')}finally{clearTimeout(timeout)}}
function showRelease(id){const t=releases.get(id);if(!t)return;openSheet('OFFICIAL RELEASE',`<img class="sheet-cover release-cover" src="${esc(t.cover)}" alt="${esc(t.album)}"><h2 translate="no">${esc(t.title)}</h2><p>${esc(t.artist)}<br>${esc(t.album)} · ${format(t.duration)}</p><p>Play this release in Echo using your own audio file. Artwork and song details will be attached to the file, and matching lyrics will be looked up automatically.</p><div class="action-menu"><button data-import-release="${esc(t.id)}">${icon('upload')} Import my audio file</button><button data-choose-release="${esc(t.id)}">${icon('library')} Choose a file from my library</button></div><a class="apple-music-link" href="${esc(t.url)}" target="_blank" rel="noopener">Listen on Apple Music ${icon('arrow')}</a><p class="release-fineprint">Apple Music playback is subject to its subscription and regional availability. Echo does not include a commercial streaming subscription.</p>`)}
function chooseReleaseFile(id){const t=releases.get(id);if(!t)return;const imported=tracks.filter(t=>t.local);openSheet('YOUR MUSIC, MATCHED',`<h2>Choose your recording.</h2><p>Match your copy of ${esc(t.title)} to its official details.</p>${imported.length?imported.map(file=>`<div class="sheet-track"><img src="${esc(file.cover)}" alt=""><button class="sheet-track-info" data-attach-release="${esc(file.id)}" data-release-id="${esc(id)}"><strong>${esc(file.title)}</strong><small>${esc(file.artist)} · ${format(file.duration)}</small></button></div>`).join(''):'<p>Import an audio file first to add it to your library.</p>'}<div class="form-row"><button class="primary-btn" data-import-release="${esc(id)}">Import my audio file</button></div>`)}
async function attachReleaseFile(id,releaseId){const t=getTrack(id),release=releases.get(releaseId);if(!t?.local||!release)return;const updated={...t,title:release.title,artist:release.artist,album:release.album,cover:release.cover,mood:release.mood};try{await dbRequest('readwrite',store=>store.put({...updated,src:undefined}));Object.assign(t,updated);lyricCache.delete(id);sheet.close();playTrack(id,[id]);openNowPlaying();loadLyrics(t,true);if(view==='library')render()}catch{toast('The file could not be updated.')}}
