let youtubeResults=[],youtubeTimer=null,youtubeController=null,youtubeEpoch=0,youtubeContinuation=null,youtubeFilter='songs',youtubeLoading=false;
function youtubeTrack(video){return {id:'youtube-'+video.videoId,videoId:video.videoId,title:video.title||'YouTube 视频 '+video.videoId,artist:video.artist||'YouTube',album:video.album||'YouTube Music',mood:'YouTube',duration:Number(video.duration)||0,category:EchoMusicLibrary.classify(video),cover:video.cover?safeArtwork(video.cover):'https://i.ytimg.com/vi/'+video.videoId+'/hqdefault.jpg',src:'youtube:'+video.videoId,provider:'youtube',remote:true,...(video.artistId?{artistId:video.artistId}:{}),...(video.albumId?{albumId:video.albumId}:{}),permalink:'https://www.youtube.com/watch?v='+video.videoId}}
function videoCard(video){return `<button class="video-card" data-video="${video.videoId}"><div><img src="${esc(getTrack('youtube-'+video.videoId)?.cover||video.cover||'https://i.ytimg.com/vi/'+video.videoId+'/hqdefault.jpg')}" alt="${esc(video.title)}" loading="lazy"><span>${icon('play')}</span></div><strong>${esc(video.title)}</strong><small>${esc(video.artist)}</small></button>`}
function parseYouTubeURL(value){try{const url=new URL(value.trim());if(!['https:','http:'].includes(url.protocol))return null;const host=url.hostname.toLowerCase().replace(/^www\./,'');let id=null;if(host==='youtu.be')id=url.pathname.split('/')[1];else if(['youtube.com','m.youtube.com','music.youtube.com','youtube-nocookie.com'].includes(host)){id=url.searchParams.get('v');if(!id&&/^\/(shorts|embed|live)\//.test(url.pathname))id=url.pathname.split('/')[2]}return /^[A-Za-z0-9_-]{11}$/.test(id||'')?id:null}catch{return null}}
function playYouTube(videoId,video=null){if(!/^[A-Za-z0-9_-]{11}$/.test(videoId))return;const id='youtube-'+videoId;if(!getTrack(id)){const item=youtubeFeatured.find(t=>t.videoId===videoId)||video||{videoId};tracks.push(youtubeTrack(item))}playTrack(id,youtubeResults.some(t=>t.id===id)?youtubeResults.map(t=>t.id):youtubeFeatured.some(t=>t.videoId===videoId)?youtubeFeatured.map(t=>'youtube-'+t.videoId):[id]);rememberOnline()}
function youtubeForm(initial=''){openSheet('YOUTUBE',`<h2>添加 YouTube</h2><form id="youtube-form"><label class="form-field">视频或 YouTube Music 链接<input type="url" name="url" required value="${esc(initial)}" inputmode="url"></label><label class="form-field">歌曲名（可选）<input name="title" maxlength="180"></label><label class="form-field">歌手（可选）<input name="artist" maxlength="180"></label><button class="primary-btn" type="submit">${icon('play')} 播放</button><p class="form-message" role="status"></p></form>`)}
function cancelYouTubeSearch(){clearTimeout(youtubeTimer);youtubeController?.abort();youtubeEpoch++;youtubeLoading=false}
function scheduleYouTubeSearch(wait=350){cancelYouTubeSearch();youtubeResults=[];youtubeContinuation=null;const area=$('#search-results');if(!area)return;const clear=$('#clear-search');if(clear)clear.hidden=!query;const term=query.trim()||(searchCategory!=='全部'?searchCategory:''),videoId=parseYouTubeURL(term);if(videoId){youtubeResults=[youtubeTrack({videoId})];youtubeResults.forEach(t=>{if(!getTrack(t.id))tracks.push(t)});renderYouTubeResults();return}if(!term){area.innerHTML=`<div class="section-heading"><h2>听点什么</h2></div><div class="video-grid">${youtubeFeatured.map(videoCard).join('')}</div>`;return}if(!window.ECHO_CONFIG?.supabaseUrl&&!window.ECHO_CONFIG?.youtubeApiKey){area.innerHTML=empty('搜索服务未连接','连接音乐搜索后端后即可在这里搜歌。','<button class="secondary-btn" id="youtube-search-retry">重试</button>');return}area.innerHTML='<div class="catalog-loading" role="status">正在搜索音乐库…</div>';youtubeTimer=setTimeout(()=>fetchYouTubeSearch(),wait)}
function decodeTitle(value){const text=document.createElement('textarea');text.innerHTML=value;return text.value}
async function fetchYouTubeSearch(append=false){if(youtubeLoading||view!=='search'||searchSource!=='youtube')return;youtubeLoading=true;const epoch=youtubeEpoch,term=[query.trim(),searchCategory!=='全部'?searchCategory:''].filter(Boolean).join(' ');youtubeController=new AbortController();const controller=youtubeController,timeout=setTimeout(()=>controller.abort(),18000);const more=$('#youtube-more');if(append&&more){more.disabled=true;more.textContent='正在加载…'}try{const config=window.ECHO_CONFIG||{};let response,result;if(config.supabaseUrl&&config.supabaseAnonKey){response=await fetch(config.supabaseUrl+'/functions/v1/youtube-search',{method:'POST',signal:controller.signal,credentials:'omit',headers:{'Content-Type':'application/json',apikey:config.supabaseAnonKey},body:JSON.stringify({q:term,filter:youtubeFilter,...(append&&youtubeContinuation?{continuation:youtubeContinuation}:{})})});result=await response.json()}else{const url=new URL('https://www.googleapis.com/youtube/v3/search');for(const[key,value]of Object.entries({key:config.youtubeApiKey,part:'snippet',q:term,type:'video',videoCategoryId:'10',videoEmbeddable:'true',maxResults:'20',safeSearch:'moderate',...(append&&youtubeContinuation?{pageToken:youtubeContinuation}:{})}))url.searchParams.set(key,value);response=await fetch(url,{signal:controller.signal,credentials:'omit'});result=await response.json();if(response.ok)result={items:(result.items||[]).map(x=>({videoId:x.id?.videoId,title:decodeTitle(x.snippet?.title||''),artist:decodeTitle(x.snippet?.channelTitle||'')})),continuation:result.nextPageToken||null}}if(epoch!==youtubeEpoch||view!=='search'||searchSource!=='youtube')return;if(!response.ok)throw new Error(response.status===429?'搜索次数较多，请稍后重试。':response.status===504?'搜索超时，请重试。':'暂时无法连接音乐搜索，请重试。');if(!Array.isArray(result.items))throw new Error('搜索响应异常，请重试。');const found=result.items.filter(x=>/^[A-Za-z0-9_-]{11}$/.test(x.videoId)).map(youtubeTrack);youtubeResults=[...new Map((append?[...youtubeResults,...found]:found).map(t=>[t.id,t])).values()];youtubeContinuation=result.continuation||null;for(const track of youtubeResults){const existing=getTrack(track.id);if(existing)Object.assign(existing,track);else tracks.push(track)}renderYouTubeResults()}catch(error){if(epoch===youtubeEpoch&&view==='search'&&searchSource==='youtube'){const message=error.name==='AbortError'?'搜索超时，请重试。':error.message;if(append){toast(message);if(more?.isConnected){more.disabled=false;more.textContent='加载更多'}}else{const area=$('#search-results');if(area)area.innerHTML=empty('暂时无法搜索',message,'<button class="primary-btn" id="youtube-search-retry">重试</button>')}}}finally{clearTimeout(timeout);if(epoch===youtubeEpoch)youtubeLoading=false}}
function renderYouTubeResults(){const area=$('#search-results');if(!area)return;area.innerHTML=`<div class="search-filters" role="group" aria-label="结果类型">${[['songs','歌曲'],['videos','视频']].map(([key,label])=>`<button data-youtube-filter="${key}" aria-pressed="${youtubeFilter===key}" class="${youtubeFilter===key?'active':''}">${label}</button>`).join('')}</div><div class="search-heading"><h2>${query.trim()?'搜索结果':'音乐库'}</h2><span>${youtubeResults.length} 首</span></div>${youtubeResults.length?trackRows(youtubeResults):empty('没有找到结果','试试其他歌曲名或歌手。')}${youtubeContinuation?'<div class="catalog-more"><button class="secondary-btn" id="youtube-more">加载更多</button></div>':''}`}
audio.addEventListener('videoissue',event=>showVideoIssue(event.detail));
function showVideoIssue(issue){const area=$('#youtube-feedback');area.hidden=!issue;area.replaceChildren();if(!issue)return;const message=document.createElement('p');message.textContent=issue.message;const retry=document.createElement('button');retry.id='youtube-retry';retry.type='button';retry.className='text-button';retry.textContent='重试播放';const link=document.createElement('a');link.textContent='在 YouTube 打开';link.href='https://www.youtube.com/watch?v='+audio.videoId;link.target='_blank';link.rel='noopener';area.append(message,retry);if([100,101,150].includes(issue.code)){const other=document.createElement('button');other.id='youtube-other-version';other.type='button';other.className='text-button';other.textContent='搜索其他版本';area.append(other)}area.append(link);toast(issue.message)}
audio.addEventListener('videometadata',event=>{const track=getTrack('youtube-'+event.detail.videoId);if(!track)return;const title=track.title.startsWith('YouTube 视频 ')?event.detail.title:track.title,artist=track.artist==='YouTube'?event.detail.artist:track.artist,changed=track.title!==title||track.artist!==artist||(event.detail.duration>0&&Math.abs((track.duration||0)-event.detail.duration)>1);Object.assign(track,{title,artist,uploader:event.detail.artist,duration:Number(event.detail.duration)||track.duration});if(changed){updatePlayer();rememberOnline()}});
document.addEventListener('submit',e=>{if(e.target.id==='music-search-form'){e.preventDefault();if(searchSource==='youtube')scheduleYouTubeSearch(0)}if(e.target.id==='home-search-form'){e.preventDefault();const term=$('#home-query').value.trim();if(!term)return;searchSource='youtube';setView('search');query=term;$('#music-search').value=term;renderResults()}});
for(const video of youtubeFeatured){const existing=getTrack('youtube-'+video.videoId);if(!existing)tracks.push(youtubeTrack(video));else if(video.cover)Object.assign(existing,{cover:video.cover,album:video.album||existing.album})}

