const deletedAccountIds=new Set();
let accountUid=undefined,accountEpoch=0,accountMode='signin',friendEpoch=0,accountPending=Promise.resolve();
function portableTrack(t){const item={};for(const key of ['id','title','artist','album','duration','cover','provider','videoId','remote','instrumental','mood','permalink','category','artistId','albumId'])if(t[key]!==undefined)item[key]=t[key];if(t.local){item.local=true;item.deviceOnly=true}else if(t.src&&(/^(https:|youtube:)/.test(t.src)||bundled.some(b=>b.id===t.id)))item.src=t.src;return item}
function cacheSnapshot(){return {likes:[...liked],playlists:JSON.parse(JSON.stringify(playlists)),tracks:tracks.filter(t=>liked.has(t.id)||playlists.some(p=>p.ids.includes(t.id))).map(portableTrack)}}
function registerCloudTrack(value){if(bundled.some(t=>t.id===value?.id))return;if(!value?.id||typeof value.title!=='string')return;const t={...value,mood:value.mood||'',cover:safeArtwork(value.cover)};if(value.local){t.src=undefined;t.deviceOnly=true}else if(value.provider==='youtube'&&/^youtube-[A-Za-z0-9_-]{11}$/.test(value.id)&&(!value.videoId||value.id.slice(8)===value.videoId)){t.videoId=value.id.slice(8);t.src='youtube:'+t.videoId;t.disabledSource=false}else if(value.id.startsWith('audius-')&&/^[A-Za-z0-9]+$/.test(value.id.slice(7))){t.src=CATALOG_API+'/tracks/'+value.id.slice(7)+'/stream?app_name=Echo'}else if(!bundled.some(b=>b.id===value.id)){if(!/^https:/.test(value.src||''))delete t.src}const existing=getTrack(t.id);if(existing?.file)return;if(existing)Object.assign(existing,t);else tracks.push(t)}
function cloudLike(id,state){if(!cloud.user)return;const t=getTrack(id);if(t)try{cloud.queue({type:'like',liked:state,track:portableTrack(t)})}catch{toast('同步暂不可用，本机收藏已保留。')}}
function cloudPlaylist(p){if(!cloud.user||!p)return;try{cloud.queue({type:'playlist',id:p.id,name:p.title,cover:p.cover,visibility:p.visibility||'private',tracks:p.ids.map(getTrack).filter(Boolean).map(portableTrack)})}catch{toast('同步暂不可用，本机歌单已保留。')}}
function cloudDeletePlaylist(id){if(!cloud.user)return;try{cloud.queue({type:'deletePlaylist',id})}catch{toast('删除暂未同步，请稍后重试。')}}
async function hydrateLibrary(cachedOnly=false){const uid=cloud.user?.id,epoch=accountEpoch;if(!uid)return;const data=cachedOnly?EchoLiveData.peek('library'):await EchoLiveData.read('library');if(!data||uid!==cloud.user?.id||epoch!==accountEpoch)return;const likeMap=new Map(data.likes.map(x=>[x.track_id,x.track])),listMap=new Map(data.playlists.map(p=>[p.id,{id:p.id,title:p.name,cover:p.cover||'assets/sea.jpg',visibility:p.visibility,ids:p.playlist_items.map(x=>x.track_id),trackData:p.playlist_items.map(x=>x.track)}]));for(const op of Object.values(cloud.pending(uid))){if(op.type==='like'){if(op.liked)likeMap.set(op.track.id,op.track);else likeMap.delete(op.track.id)}else if(op.type==='deletePlaylist')listMap.delete(op.id);else listMap.set(op.id,{id:op.id,title:op.name,cover:op.cover,visibility:op.visibility,ids:op.tracks.map(t=>t.id),trackData:op.tracks})}for(const t of likeMap.values())registerCloudTrack(t);for(const p of listMap.values())for(const t of p.trackData||[])registerCloudTrack(t);liked=new Set(likeMap.keys());playlists=[...listMap.values()].map(({trackData,...p})=>p);save('likes',[...liked]);save('playlists',playlists);save('library-owner',uid);rememberOnline();if(['library','liked'].includes(view))render();else renderSidebar();cloud.flush()}
async function receiveAccount(event={}){if(event.event==='EMAIL_VERIFIED'){toast('邮箱已确认，请登录。');accountMode='signin';accountPanel();return}if(event.event==='PASSWORD_RECOVERY'){accountMode='password';accountPanel();return}const uid=cloud.user?.id||null;if(uid===accountUid)return;const previous=read('library-owner','guest');if(!deletedAccountIds.has(previous))save('library-cache-'+previous,cacheSnapshot());accountUid=uid;const epoch=++accountEpoch;$('#account-btn').textContent=uid?'账号':'登录';if(!uid){const guest=read('library-cache-guest',{likes:[],playlists:[],tracks:[]});for(const t of guest.tracks||[])registerCloudTrack(t);liked=new Set(guest.likes||[]);playlists=guest.playlists||[];save('likes',[...liked]);save('playlists',playlists);save('library-owner','guest');render();return}liked=new Set();playlists=[];render();try{if(cloud.sheetMode){if(!event.identityReady)await cloud.refreshIdentity()}else await cloud.syncAdmin();if(epoch!==accountEpoch)return;if(cloud.entitlement?.account_status!=='active'){if(typeof stopChat==='function')stopChat();if(view==='artist')dismissArtistRoute();view='library';render();accountMode='signin';accountPanel();return}if(!cloud.sheetMode){await cloud.ensureProfile();if(epoch!==accountEpoch)return;await cloud.checkAdmin().catch(()=>false)}if(epoch!==accountEpoch)return;updateAccountBadge();EchoLiveData.seed('identity',{profile:cloud.profile,account:cloud.entitlement,isAdmin:cloud.isAdmin});await hydrateLibrary();EchoLiveData.wake()}catch(error){if(epoch===accountEpoch){toast('账号已登录，云端资料暂未加载。请稍后重试。');const cached=read('library-cache-'+uid,null);if(cached){for(const t of cached.tracks||[])registerCloudTrack(t);liked=new Set(cached.likes||[]);playlists=cached.playlists||[];save('library-owner',uid);render()}}}}
async function initAccount(){if(!cloud.configured){EchoAdminPage.settled();return;}cloud.addEventListener('deleted',event=>{deletedAccountIds.add(event.detail.id);try{localStorage.removeItem('echo-library-cache-'+event.detail.id);localStorage.removeItem('echo-cloud-outbox-'+event.detail.id)}catch{}});cloud.addEventListener('session',event=>{accountPending=receiveAccount(event.detail)});cloud.addEventListener('sync',event=>{const status=$('#account-sync');if(status)status.textContent=event.detail.error?'同步待重试':event.detail.pending?'正在同步':'已同步'});try{await cloud.init();await accountPending;await receiveAccount()}catch{toast('账号服务连接失败，本机功能仍可使用。')}finally{EchoAdminPage.settled()}}
function avatarMarkup(person){let url=person?.avatar_url;try{const parsed=new URL(url),project=new URL(window.ECHO_CONFIG?.supabaseUrl);if(parsed.origin!==project.origin||!parsed.pathname.startsWith('/storage/v1/object/sign/echo-avatars/'))url=null}catch{url=null}return url?`<img src="${esc(url)}" alt="${esc(person.display_name||'听友')} 的头像">`:esc((person?.display_name||'听友').slice(0,1))}
function updateAccountBadge(){const button=$('#account-btn');if(!cloud.user){button.textContent='登录';return}const markup=`${cloud.profile?.avatar_url?`<span class="account-avatar">${avatarMarkup(cloud.profile)}</span>`:''}<span class="account-name">${esc(cloud.profile?.display_name||'账号')}</span>`;if(button.innerHTML!==markup)button.innerHTML=markup}
function membershipDate(value){const date=new Date(value);return Number.isFinite(date.getTime())?date.toLocaleString(EchoI18n.locale,{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}):null}
function membershipCard(membership){
 const raw=membership?.premium_until,date=raw?new Date(raw):null,valid=date&&Number.isFinite(date.getTime()),expired=valid&&date.getTime()<=Date.now(),status=membership?.account_status||'active',premium=membership?.tier==='premium'&&!expired;
 const label=!membership?'会员资料待刷新':status==='suspended'?'账号已暂停':status==='disabled'?'账号已停用':expired?'Premium 已到期':premium?'Premium':'免费账号';
 const detail=valid?`<span>到期时间</span><time class="membership-date" datetime="${date.toISOString()}" translate="no">${esc(membershipDate(raw))}</time>`:raw?'<span>到期时间</span><strong>到期时间暂不可用</strong>':premium?'<span>到期时间</span><strong>未设置到期时间</strong>':!membership?'<strong>刷新账号资料后显示会员状态</strong>':'<strong>当前为免费账号</strong>';
 return `<section class="membership-card" data-tier="${premium?'premium':'free'}" data-status="${esc(status!=='active'?status:expired?'expired':'active')}" aria-label="会员状态"><div class="membership-card-heading"><span>会员状态</span><span class="membership-tag">${premium?icon('check'):''}${label}</span></div><p class="membership-expiry">${detail}</p><button class="text-button membership-redeem" id="redeem-membership">兑换 Premium</button></section>`;
}
