async function accountOperation({message,title,detail,action,done=accountPanel,allowSessionChange=false}){
 const operation=EchoFeedback.start({message,allowSessionChange});try{await action();operation.success({title,message:typeof detail==='function'?detail():detail||'',restore:false,onDone:done})}catch(error){operation.failure({message:error.message||'操作失败，请重试。'})}
}
let authEmail='';
function accountPanel(){
 if(!cloud.configured){openSheet('账号','<h2>登录</h2><p>账号服务尚未连接。</p><button class="primary-btn" id="continue-local">继续使用</button>');return}
 if(cloud.user&&!['password','change','reset'].includes(accountMode)){
  const p=cloud.profile,handle=p?.handle||'',name=p?.display_name||'',membership=cloud.entitlement,status=membership?.account_status||'active',active=status==='active';
  openSheet('账号',`<div class="profile-heading"><span class="profile-avatar">${avatarMarkup(p)}</span><div><h2>${esc(name||'账号')}</h2><p>${esc(cloud.user.email||'')}</p></div></div>${membershipCard(membership)}<div class="avatar-actions"><button class="secondary-btn" id="upload-avatar" ${active?'':'disabled'}>上传头像</button>${p?.avatar_path?'<button class="text-button" id="remove-avatar">移除头像</button>':''}<span id="avatar-message" role="status"></span></div><form id="profile-form"><fieldset ${active?'':'disabled'}><label class="form-field">昵称<input name="display_name" value="${esc(name)}" required maxlength="40" autocomplete="nickname"></label><label class="form-field">用户名<input name="handle" value="${esc(handle)}" required minlength="3" maxlength="24" pattern="[a-z0-9_]+" autocapitalize="none" autocomplete="username"></label><button class="primary-btn" type="submit">保存</button><p class="form-message" role="status"></p></fieldset></form><div class="account-actions"><button class="text-button" data-auth-mode="change">修改密码</button><button class="text-button" data-auth-mode="reset">通过邮件重设密码</button><span id="account-sync">${cloud.lastSyncError?'同步待重试':Object.keys(cloud.pending()).length?'正在同步':'已同步'}</span><button class="text-button" id="retry-cloud-sync">刷新账号资料</button>${cloud.isAdmin?'<button class="text-button" id="manage-users">管理中心</button>':''}${active?'<button class="text-button" id="import-device-library">合并本机收藏与歌单</button>':''}<button class="text-button" id="signout-account">退出登录</button><button class="text-button danger" id="delete-account-confirm">删除账号</button></div>`);sheet.dataset.panel='account';return;
 }
 const mode=accountMode,title={signin:'登录',signup:'注册',reset:'重设密码',password:'设置新密码',change:'修改密码'}[mode]||'登录',setting=['password','change'].includes(mode);
 openSheet('账号',`<h2>${title}</h2>${cloud.sheetMode&&mode==='signin'?'<p class="muted-line">原有账号已迁移，请先通过「忘记密码」设置新密码。</p>':''}<form id="auth-form" data-mode="${mode}">${!setting?`<label class="form-field">邮箱<input name="email" type="email" required autocomplete="email" value="${esc(mode==='reset'?cloud.user?.email||authEmail:authEmail)}"></label>`:''}${mode==='change'?'<label class="form-field">当前密码<input name="current_password" type="password" required autocomplete="current-password"></label>':''}${mode!=='reset'?`<label class="form-field">${setting?'新密码':'密码'}<input name="password" type="password" required minlength="${mode==='signin'?1:12}" autocomplete="${mode==='signin'?'current-password':'new-password'}"></label>`:''}${setting||mode==='signup'?'<label class="form-field">确认密码<input name="confirm_password" type="password" required minlength="12" autocomplete="new-password"></label>':''}<button class="primary-btn" type="submit">${title}</button><p class="form-message" role="status"></p></form><div class="auth-links">${mode==='signin'?'<button class="text-button" data-auth-mode="signup">创建账号</button><button class="text-button" data-auth-mode="reset">忘记密码</button>':`<button class="text-button" data-auth-mode="signin">${cloud.user?'返回账号':'返回登录'}</button>`}</div>`);
 sheet.dataset.panel='account';
}
async function importDeviceLibrary(){if(!cloud.user)return;const guest=read('library-cache-guest',null);if(!guest){toast('没有待合并的本机资料。');return}for(const t of guest.tracks||[])registerCloudTrack(t);for(const id of guest.likes||[]){liked.add(id);cloudLike(id,true)}for(const p of guest.playlists||[]){if(!playlists.some(x=>x.id===p.id))playlists.push(p);cloudPlaylist(p)}save('likes',[...liked]);save('playlists',playlists);render();toast('本机收藏和歌单已加入同步队列。')}
function paintFriends(list){if(view!=='friends'||!$('#friend-list')||!cloud.user)return;const signature=EchoDataSignature(list),area=$('#friend-list');if(area.dataset.signature===signature)return;area.dataset.signature=signature;const incoming=list.filter(x=>x.status==='pending'&&x.addressee_id===cloud.user.id),sent=list.filter(x=>x.status==='pending'&&x.requester_id===cloud.user.id),friends=list.filter(x=>x.status==='accepted');const row=(r,type)=>`<div class="person-row"><span class="person-avatar">${avatarMarkup(r.person)}</span><div><strong>${esc(r.person?.display_name||'听友')}</strong><small>@${esc(r.person?.handle||'')}</small></div><span class="person-actions">${type==='incoming'?`<button class="secondary-btn" data-friend-accept="${r.id}">接受</button><button class="text-button" data-friend-remove="${r.id}">拒绝</button>`:type==='sent'?`<button class="text-button" data-friend-remove="${r.id}">取消申请</button>`:`<button class="secondary-btn" data-chat-person="${r.person.id}" data-person-name="${esc(r.person.display_name||'好友')}" data-person-handle="${esc(r.person.handle||'')}">聊天</button><button class="text-button" data-friend-open="${r.person.id}">歌单</button><button class="text-button" data-friend-remove="${r.id}">移除</button>`}</span></div>`;const groups=[{id:'incoming',title:'好友申请',rows:incoming,type:'incoming'},{id:'friends',title:'好友',rows:friends,type:'friend'},{id:'sent',title:'已发送',rows:sent,type:'sent'}].filter(group=>group.rows.length||group.id==='friends');EchoPatchRows(area,groups.map(({id,title})=>({id,title})),group=>group.id,group=>'<section class="friend-group"><div class="section-heading"><h2>'+EchoI18n.t(group.title)+'<span class="friend-count"></span></h2></div><div class="friend-group-rows"></div></section>');for(const group of groups){const section=[...area.children].find(node=>node.dataset.liveKey===group.id),count=section.querySelector('.friend-count'),label=group.id==='friends'?' · '+group.rows.length:'';if(count.textContent!==label)count.textContent=label;EchoPatchRows(section.querySelector('.friend-group-rows'),group.rows,item=>item.id,item=>row(item,group.type));if(!group.rows.length&&!section.querySelector('.muted-line'))section.querySelector('.friend-group-rows').innerHTML='<p class="muted-line">还没有好友。</p>'}}
async function renderFriends(){const epoch=++friendEpoch,uid=cloud.user?.id;if(!cloud.user){main.innerHTML=`<div class="view-heading compact-heading"><h1>好友</h1></div>${empty('登录后添加好友','使用用户名查找好友。','<button class="primary-btn" id="account-btn-inline">登录</button>')}`;return}main.innerHTML=`<div class="view-heading compact-heading"><h1>好友</h1></div><form id="people-search" class="people-search"><label for="person-query">用户名</label><div><input id="person-query" name="handle" required minlength="3" maxlength="24" autocapitalize="none"><button class="primary-btn" type="submit">查找</button></div></form>${typeof EchoCommunity!=='undefined'?EchoCommunity.friendMarkup():''}<div id="people-results"></div><div id="friend-list" role="status">正在加载…</div>`;try{const list=await EchoLiveData.read('friends');if(epoch!==friendEpoch||view!=='friends'||cloud.user?.id!==uid)return;paintFriends(list)}catch{if(epoch!==friendEpoch||view!=='friends'||cloud.user?.id!==uid)return;if(!$('#friend-list').children.length)$('#friend-list').innerHTML='<p>暂时无法加载好友，请重试。</p>'}}
async function showFriendPlaylists(id){const uid=cloud.user?.id;openSheet('好友歌单','<h2>歌单</h2><p>正在加载…</p>');sheet.dataset.panel='friend-playlists';const content=$('#sheet-content'),token=crypto.randomUUID();sheet.dataset.request=token;try{const data=await cloud.sharedPlaylists(id);if(cloud.user?.id!==uid||!sheet.open||sheet.dataset.panel!=='friend-playlists'||sheet.dataset.request!==token||$('#sheet-content')!==content)return;for(const p of data){const entries=(p.playlist_items||[]).sort((a,b)=>a.position-b.position);entries.forEach(item=>registerCloudTrack(item.track));sharedCollections.set(p.id,{id:p.id,title:p.name,cover:p.cover||'assets/sea.jpg',ids:entries.map(t=>t.track_id)})}$('#sheet-content').innerHTML=`<h2>好友歌单</h2>${data.length?data.map(p=>`<button translate="no" class="friend-playlist" data-collection="${esc(p.id)}">${icon('library')} ${esc(p.name)} ${icon('arrow')}</button>`).join(''):'<p>这位好友还没有分享歌单。</p>'}`}catch{if(cloud.user?.id!==uid||!sheet.open||sheet.dataset.panel!=='friend-playlists'||sheet.dataset.request!==token)return;$('#sheet-content').innerHTML='<h2>歌单</h2><p>暂时无法加载，请重试。</p>'}}
document.addEventListener('click',async e=>{const target=e.target.closest('button');if(!target)return;const d=target.dataset;try{if(d.authMode){accountMode=d.authMode;accountPanel()}if(target.id==='continue-local')sheet.close();if(target.id==='account-btn-inline')accountPanel();if(target.id==='signout-account')await accountOperation({message:'正在退出登录…',title:'已退出登录',action:()=>cloud.signOut(),allowSessionChange:true,done:()=>{authEmail='';accountMode='signin';accountPanel()}});if(target.id==='retry-cloud-sync')await accountOperation({message:'正在刷新账号资料…',title:'账号资料已刷新',detail:()=>cloud.lastSyncError?'部分收藏仍待同步。':'账号和会员资料已更新。',action:async()=>{if(cloud.sheetMode)await cloud.refreshIdentity();else{await cloud.syncAdmin();await cloud.ensureProfile();await cloud.checkAdmin().catch(()=>false)}if(cloud.entitlement?.account_status!=='active')throw Error('账号当前不可用。');updateAccountBadge();await cloud.flush();await EchoLiveData.refresh('library',{force:true});await hydrateLibrary(true)}});if(d.friendRequest){target.disabled=true;await cloud.requestFriend(d.friendRequest);target.textContent='已申请'}if(d.friendAccept){await cloud.acceptFriend(d.friendAccept);renderFriends()}if(d.friendRemove){await cloud.removeFriend(d.friendRemove);renderFriends()}if(d.friendOpen)showFriendPlaylists(d.friendOpen);if(d.playlistPrivacy){if(!cloud.user){accountPanel();return}const p=playlists.find(p=>p.id===d.playlistPrivacy);p.visibility=p.visibility==='friends'?'private':'friends';save('playlists',playlists);cloudPlaylist(p);openCollection(p.id)}if(target.id==='delete-account-confirm')openSheet('删除账号','<h2>删除账号？</h2><p>账号、云端收藏、歌单和好友关系将被永久删除。本机音频文件不会删除。</p><button class="primary-btn danger" id="delete-account-final">确认删除账号</button>');if(target.id==='delete-account-final')await accountOperation({message:'正在删除账号…',title:'账号已删除',detail:'账号资料已删除。',action:()=>cloud.deleteAccount(),allowSessionChange:true,done:()=>sheet.close()});}catch(error){target.disabled=false;toast(error.message||'操作失败，请重试。')}});
document.addEventListener('submit',async event=>{
 if(!['auth-form','profile-form','people-search'].includes(event.target.id))return;event.preventDefault();
 const form=event.target;if(form.dataset.busy==='true')return;const button=$('button[type="submit"]',form),message=$('.form-message',form),data=new FormData(form),mode=form.dataset.mode;
 if(form.id==='auth-form'&&['signup','password','change'].includes(mode)&&String(data.get('password')||'')!==String(data.get('confirm_password')||'')){if(message)message.textContent='两次输入的密码不一致。';return}
 form.dataset.busy='true';button.disabled=true;if(message)message.textContent='';let operation=null;
 try{
  if(form.id==='auth-form'){
   const email=String(data.get('email')||'').trim(),password=String(data.get('password')||'');if(email)authEmail=email;
   operation=EchoFeedback.start({message:({signin:'正在登录…',signup:'正在创建账号…',reset:'正在提交重设请求…',change:'正在修改密码…',password:'正在重设密码…'})[mode]||'正在处理…',allowSessionChange:true});
   const returnToAccount=()=>{accountMode='signin';accountPanel()};
   if(mode==='signup'){
    const result=await cloud.signUp(email,password);form.reset();operation.success({title:result.session?'注册成功':'请检查邮箱',message:result.session?'账号已创建，可以开始听歌。':'请打开邮箱中的确认链接完成注册。已有账号可以直接登录。',actionLabel:result.session?'继续听歌':'返回登录',restore:false,onDone:result.session?()=>sheet.close():returnToAccount});
   }else if(mode==='signin'){
    await cloud.signIn(email,password);if(operation.current()){if(cloud.sheetMode)await cloud.refreshIdentity();else await cloud.syncAdmin()}if(cloud.entitlement?.account_status&&cloud.entitlement.account_status!=='active')throw Error('账号当前不可用。');form.reset();operation.success({title:'登录成功',message:'欢迎回来，你的音乐已准备就绪。',actionLabel:'继续听歌',restore:false,onDone:()=>sheet.close()});
   }else if(mode==='reset'){
    await cloud.resetPassword(email);operation.success({title:'请检查邮箱',message:cloud.sheetMode?'如果邮箱已注册，会收到重设密码的邮件。链接有效期为 30 分钟，仅可使用一次。':'如果邮箱已注册，会收到重设密码的邮件。请在发起重设的浏览器中打开链接。',actionLabel:'返回登录',restore:false,onDone:returnToAccount});
   }else{
    await cloud.updatePassword(password,mode==='change'?String(data.get('current_password')||''):undefined);form.reset();accountMode='signin';operation.success({title:mode==='change'?'密码已修改':'密码已重设',message:'下次登录请使用新密码。',actionLabel:cloud.user?'返回账号':'返回登录',restore:false,onDone:returnToAccount});receiveAccount();
   }
  }else if(form.id==='profile-form'){
   operation=EchoFeedback.start({message:'正在保存资料…'});await cloud.updateProfile(String(data.get('handle')).trim().toLowerCase(),String(data.get('display_name')));updateAccountBadge();operation.success({title:'资料已保存',message:'账号资料已更新。',restore:false,onDone:accountPanel});
  }else{
   const results=await cloud.searchPeople(String(data.get('handle')).trim());if(form.isConnected)$('#people-results').innerHTML=results.length?results.map(person=>`<div class="person-row"><span class="person-avatar">${avatarMarkup(person)}</span><div><strong>${esc(person.display_name)}</strong><small>@${esc(person.handle)}</small></div><button class="secondary-btn" data-friend-request="${person.id}">添加</button></div>`).join(''):'<p class="muted-line">没有找到这个用户名。</p>';
  }
 }catch(error){
  const text=error.message==='Invalid login credentials'?'邮箱或密码不正确。':error.code==='email_address_not_authorized'?'邮件服务尚未完成配置，暂时无法发送邮件。':error.code==='email_not_confirmed'?'请先确认邮箱后登录。':error.code==='over_email_send_rate_limit'?'邮件发送次数已达服务限制，请稍后重试。':error.code==='reauthentication_needed'?'请重新登录后修改密码。':error.message;
  if(operation)operation.failure({title:form.id==='profile-form'?'保存未完成':({signin:'登录未完成',signup:'注册未完成',reset:'请求未完成',change:'修改未完成',password:'重设未完成'})[mode]||'操作未完成',message:text});else if(message)message.textContent=text;else toast(text);
 }finally{form.dataset.busy='false';button.disabled=false}
});
sheet.addEventListener('close',()=>{$$('input[type="password"]',sheet).forEach(input=>input.value='')});
document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;if(button.id==='upload-avatar')$('#avatar-file-input').click();if(button.id==='remove-avatar')await accountOperation({message:'正在移除头像…',title:'头像已移除',action:async()=>{await cloud.removeAvatar();updateAccountBadge()}})});
$('#avatar-file-input').addEventListener('change',async event=>{const file=event.target.files[0],uid=cloud.user?.id;if(!file||!uid)return;try{await accountOperation({message:'正在处理并上传头像…',title:'头像已更新',action:async()=>{const photo=await EchoProfilePhoto.prepare(file);if(cloud.user?.id!==uid)throw Error('登录状态已改变。');await cloud.uploadAvatar(photo);updateAccountBadge();accountMode='signin'}})}finally{event.target.value=''}});

window.addEventListener('online',()=>cloud.flush());

const player=new EchoPlayerCore({audio,resolveTrack:getTrack,storage:window.localStorage,mediaSession:navigator.mediaSession||null,baseURL:location.href});
const savedPlayerPreferences=new Map();
function syncPlayerState(state){EchoAppearance.setPlayback(state.playing);current=state.currentId||current;queue=[...state.queue];shuffle=state.shuffle;repeat=state.repeat;for(const [key,value]of Object.entries({current,queue,shuffle,repeat,volume:state.volume})){const serialized=JSON.stringify(value);if(savedPlayerPreferences.get(key)!==serialized){savedPlayerPreferences.set(key,serialized);save(key,value)}}updateVolumeControls(state.volume);updateControls();updatePlaybackStatus(state);}
function updatePlaybackStatus(state){const loading=['loading','buffering'].includes(state.status);$$('.toggle-play').forEach(button=>{button.classList.toggle('is-buffering',loading);button.setAttribute('aria-busy',String(loading));if(state.status==='error')button.setAttribute('aria-label','Retry playback')});const status=$('#playback-status');status.textContent=loading?'正在加载…':state.status==='error'?'暂时无法播放':state.status==='ended'?'队列已结束':'';status.hidden=!status.textContent;$('#retry-playback').hidden=state.status!=='error';}
player.addEventListener('statechange',event=>syncPlayerState(event.detail));
player.addEventListener('trackchange',()=>{seekDrafts.clear();seekEditing.clear();syncPlayerState(player.getSnapshot());updatePlayer();refreshTrackRows()});
player.addEventListener('timeupdate',updateProgress);
player.addEventListener('error',event=>toast(event.detail.message));
window.addEventListener('pagehide',()=>player.persist());
document.addEventListener('visibilitychange',()=>{if(document.hidden){player.persist();}});
async function init(){player.addEventListener('statechange',()=>EchoLiveData.wake());applyPlatform();const cleanURL=new URL(location.href);if(cleanURL.searchParams.has('v')){cleanURL.searchParams.delete('v');history.replaceState(history.state,'',cleanURL.pathname+cleanURL.search+cleanURL.hash)}render();try{db=await openDatabase();const saved=await dbRequest('readonly',s=>s.getAll());for(const t of saved)tracks.push({...t,cover:safeArtwork(t.cover),src:URL.createObjectURL(t.file)})}catch{toast('Device storage is unavailable. Included music still works.')}queue=queue.filter(id=>getTrack(id));if(!getTrack(current))current='sanctuary';liked=new Set([...liked].filter(id=>getTrack(id)));playlists.forEach(p=>p.ids=p.ids.filter(id=>getTrack(id)));player.restore({currentId:current,queue,shuffle,repeat,volume:Number(read('volume',.8))});render();updatePlayer();const shared=new URLSearchParams(location.hash.slice(1)).get('track');if(shared&&!getTrack(shared)&&/^youtube-[A-Za-z0-9_-]{11}$/.test(shared))tracks.push(youtubeTrack({videoId:shared.slice(8)}));if(shared&&!getTrack(shared)&&/^audius-[a-zA-Z0-9]+$/.test(shared)){try{const result=await catalogRequest('/tracks/'+shared.slice(7));if(streamable(result.data)){tracks.push(mapCatalogTrack(result.data));rememberOnline()}}catch{toast('This shared song is unavailable.')}}if(shared&&getTrack(shared)){player.select(shared,{autoplay:false});openNowPlaying()}const artistRoute=new URLSearchParams(location.hash.slice(1)),artistTrack=artistRoute.get('artist');if(artistTrack){if(!getTrack(artistTrack)&&/^youtube-[A-Za-z0-9_-]{11}$/.test(artistTrack))tracks.push(youtubeTrack({videoId:artistTrack.slice(8)}));if(getTrack(artistTrack)){await openArtist(artistTrack,{push:false});const releaseId=artistRoute.get('release');if(releaseId&&view==='artist')openArtistRelease(releaseId,{push:false})}}if('serviceWorker'in navigator)navigator.serviceWorker.register('sw.js',{updateViaCache:'none'}).catch(()=>{});initAccount();audio.ready().catch(()=>{});}
init();
